package net.civeira.phylax.feature.observe.source.sync;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.access.oauthclient.domain.gateway.OauthClientFilter;
import net.civeira.phylax.feature.access.oauthclient.domain.gateway.OauthClientQueryRepositoryGateway;
import net.civeira.phylax.feature.observe.source.ObservedOriginReader;
import net.civeira.phylax.feature.observe.source.OriginRef;

/**
 * Every oauth client as an origin, for the reconciliation at startup.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class OauthClientObservedOriginReader implements ObservedOriginReader {

  private final OauthClientQueryRepositoryGateway gateway;

  @Override
  public String originType() {
    return "app";
  }

  @Override
  public List<OriginRef> readAll() {
    return gateway.list(OauthClientFilter.builder().build()).stream()
        .map(OauthClientObservedSourceSync::toOrigin).toList();
  }
}
